import type { Record } from '../../../db/Record'
import type { TableName } from '../../../db/Table'
import type { CustomVariableType } from './Custom'

/**
 * Configuration type for custom with label variables (macro)
 */
export type CustomWithLabelVariableType<
    MacroRefTable extends TableName = 'sys_ui_macro',
    SummaryRefTable extends TableName = 'sys_ui_macro',
    WidgetRefTable extends TableName = 'sp_widget',
    MacroponentRefTable extends TableName = 'sys_ux_macroponent',
    TopicRefTable extends TableName = 'sys_cs_topic',
    Type extends
        | Record<MacroRefTable>
        | Record<SummaryRefTable>
        | Record<WidgetRefTable>
        | Record<MacroponentRefTable>
        | Record<TopicRefTable>
        | Now.Internal.ExplicitKey
        | string =
        | Record<MacroRefTable>
        | Record<SummaryRefTable>
        | Record<WidgetRefTable>
        | Record<MacroponentRefTable>
        | Record<TopicRefTable>
        | Now.Internal.ExplicitKey
        | string,
> = CustomVariableType<MacroRefTable, SummaryRefTable, WidgetRefTable, MacroponentRefTable, TopicRefTable, Type>

/**
 * A Variable for a custom UI component field with a label.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the custom UI component variable including:
 *   * **question** - Question text displayed to the user
 *   * **macro** - Reference to a sys_ui_macro record
 *   * **summaryMacro** - Reference to a sys_ui_macro record
 *   * **widget** - Reference to a sp_widget record
 *   * **macroponent** - Reference to a sys_ux_macroponent record
 *   * **topicBlock** - Reference to a sys_cs_topic record
 *   * And all other properties from the base Variable type
 *
 * @remarks
 * The following properties are not supported for custom UI component variables:
 * - mandatory
 * - hidden
 * - readOnly
 */
export function CustomWithLabelVariable(config: CustomWithLabelVariableType) {
    return config
}
